-- ============================================
-- LUMA — Enrichissement Thématiques 16 (Australie) et 17 (Sport) : un scénario long chacun
-- ============================================

update scenarios set content = '{"characters": {"friend": "ton compagnon de route"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "Starting in Cairns, ending in Melbourne — that''s a huge stretch of coast!", "text_fr": "On commence à Cairns, on finit à Melbourne — c''est un énorme tronçon de côte !", "choices": [{"text": "Let''s plan stops at the Whitsundays and Byron Bay along the way.", "next": "n2"}, {"text": "Let''s stay flexible and decide stops as we go.", "next": "n2b"}]}, "n2": {"speaker": "friend", "text": "Great picks. The Whitsundays were incredible — what''s next after Byron?", "text_fr": "Excellents choix. Les Whitsundays étaient incroyables — quoi après Byron ?", "choices": [{"text": "Let''s stop in Sydney for a few days to work and refill the budget.", "next": "n3"}]}, "n2b": {"speaker": "friend", "text": "(you discover a hidden gem beach town not in any guidebook) This spontaneous stop might be the best one yet!", "text_fr": "(vous découvrez une petite ville balnéaire cachée absente de tout guide) Cet arrêt spontané pourrait être le meilleur de tous !", "choices": [{"text": "Let''s stop in Sydney next for some work to refill the budget.", "next": "n3"}]}, "n3": {"speaker": "friend", "text": "Smart, we could both pick up some casual hospitality work there.", "text_fr": "Malin, on pourrait tous les deux trouver du travail occasionnel dans l''hôtellerie là-bas.", "choices": [{"text": "Exactly the plan, then we finish the trip down to Melbourne.", "next": "n4"}, {"text": "Actually, maybe we should each find different jobs to build more contacts.", "next": "n4b"}]}, "n4": {"speaker": "friend", "text": "(after Sydney) Budget''s refilled, ready for the final stretch!", "text_fr": "(après Sydney) Budget renfloué, prêt pour la dernière étape !", "choices": [{"text": "Let''s make these last few days count.", "next": "n5"}]}, "n4b": {"speaker": "friend", "text": "That''s actually smart — more contacts means more future opportunities.", "text_fr": "C''est en fait malin — plus de contacts veut dire plus d''opportunités futures.", "choices": [{"text": "Exactly my thinking. Ready for Melbourne now?", "next": "n5"}]}, "n5": {"speaker": "friend", "text": "This entire trip has honestly changed how I see this country.", "text_fr": "Ce voyage a honnêtement changé ma vision de ce pays.", "choices": [{"text": "Same here — working and traveling together, best of both worlds.", "next": "end_journey"}]}, "end_journey": {"speaker": "friend", "text": "What an incredible way to see this country, working and traveling both.", "text_fr": "Quelle incroyable façon de découvrir ce pays, en travaillant et en voyageant à la fois.", "end": true, "ending_label": "Road trip travail-voyage réussi de bout en bout 🏄"}}}'::jsonb, is_playable = true
where title = 'Un road trip de la côte est avec plusieurs arrêts'
  and theme_id = (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"trainer": "ton coach de course", "runner": "un autre coureur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "trainer", "text": "Twelve weeks until race day. Ready to commit to the training plan?", "text_fr": "Douze semaines avant la course. Prêt à t''engager dans le plan d''entraînement ?", "choices": [{"text": "Absolutely, I''ve been waiting for this challenge.", "next": "n2"}, {"text": "Honestly, twelve weeks feels intense — is there flexibility?", "next": "n2b"}]}, "n2": {"speaker": "trainer", "text": "(weeks later) Your long runs are improving fast, how''s your body feeling?", "text_fr": "(semaines plus tard) Tes longues sorties s''améliorent vite, comment se sent ton corps ?", "choices": [{"text": "Tired but strong, I really feel the progress.", "next": "n3"}, {"text": "Honestly, my knees have been a bit sore.", "next": "n3b"}]}, "n2b": {"speaker": "trainer", "text": "Of course, we can adjust intensity based on how your body responds.", "text_fr": "Bien sûr, on peut ajuster l''intensité selon comment ton corps répond.", "choices": [{"text": "That reassures me, let''s get started then.", "next": "n3"}]}, "n3": {"speaker": "trainer", "text": "That''s exactly what we want to hear, keep it up.", "text_fr": "C''est exactement ce qu''on veut entendre, continue comme ça.", "choices": [{"text": "Will do, feeling ready for race day.", "next": "n4"}]}, "n3b": {"speaker": "trainer", "text": "Let''s adjust your training load a bit to protect your joints.", "text_fr": "Ajustons un peu ta charge d''entraînement pour protéger tes articulations.", "choices": [{"text": "Good idea, better safe for race day.", "next": "n4"}]}, "n4": {"speaker": "runner", "text": "(race day, at mile 20) You doing okay? This is the tough part.", "text_fr": "(jour de la course, au 32e km) Ça va ? C''est la partie difficile.", "choices": [{"text": "Hanging in there, let''s push through together.", "next": "n5"}, {"text": "Honestly, I''m hitting a wall right now.", "next": "n5b"}]}, "n5": {"speaker": "runner", "text": "That''s the spirit! We''ve got this, just a few more miles.", "text_fr": "Voilà l''esprit ! On va y arriver, plus que quelques kilomètres.", "choices": [{"text": "(push through the pain, focused on the finish line)", "next": "end_finish"}]}, "n5b": {"speaker": "runner", "text": "That happens to everyone — slow your pace, breathe, and keep moving forward.", "text_fr": "Ça arrive à tout le monde — ralentis, respire, et continue d''avancer.", "choices": [{"text": "(follow the advice, finding a second wind)", "next": "end_finish_strong"}]}, "end_finish": {"speaker": "runner", "text": "We did it! Crossing that finish line together!", "text_fr": "On l''a fait ! On franchit la ligne d''arrivée ensemble !", "end": true, "ending_label": "Marathon terminé en équipe 🏅"}, "end_finish_strong": {"speaker": "runner", "text": "Look at you, pushing through that wall like a champion!", "text_fr": "Regarde-toi, surmontant ce coup de mou comme un champion !", "end": true, "ending_label": "Marathon terminé malgré l''épreuve 💪🏅"}}}'::jsonb, is_playable = true
where title = 'Préparer et courir un marathon'
  and theme_id = (select id from scenario_themes where position = 17 and language_id = (select id from languages where code = 'en'));
